(function(){
  function setAvPreview(src){
    const prev=document.getElementById("av-large-preview");
    const hint=document.getElementById("av-preview-hint");
    if(!prev)return;
    if(src){
      prev.innerHTML='<img src="'+src+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" onerror="this.parentNode.innerHTML=\'<span style=font-size:.6rem;color:var(--muted)>Bad image</span>\'"/>';
      if(hint)hint.style.display="none";
    }else{prev.innerHTML="";if(hint)hint.style.display="";}
  }
  if(_account.avatar&&!_account.avatar.startsWith("__builtin__"))setAvPreview(_account.avatar);
  let _uploadedDataUrl=null;
  const fileInput=document.getElementById("av-file-input");
  const urlInput=document.getElementById("av-url");
  if(fileInput){fileInput.addEventListener("change",function(){
    const file=this.files[0];if(!file)return;
    if(file.size>512*1024){setMsg("av-msg","Image too large (max 512 KB). Try a URL instead.",false);return;}
    const reader=new FileReader();
    reader.onload=function(ev){_uploadedDataUrl=ev.target.result;urlInput&&(urlInput.value="");setAvPreview(_uploadedDataUrl);setMsg("av-msg","",false);};
    reader.readAsDataURL(file);
  });}
  if(urlInput){urlInput.addEventListener("input",function(){
    _uploadedDataUrl=null;if(fileInput)fileInput.value="";
    const v=this.value.trim();
    if(v.startsWith("http"))setAvPreview(v);else if(!v)setAvPreview(null);
  });}
  let avLock=false;
  const saveBtn=document.getElementById("av-save-btn");
  if(saveBtn)saveBtn.onclick=async function(){
    if(avLock)return;
    let avatarVal=null;
    const urlVal=urlInput?urlInput.value.trim():"";
    if(_uploadedDataUrl){avatarVal=_uploadedDataUrl;}
    else if(urlVal){
      if(!/^https?:\/\//.test(urlVal))return setMsg("av-msg","Enter a valid https:// URL.",false);
      avatarVal=urlVal;
    }else return setMsg("av-msg","Upload a file or paste a URL.",false);
    avLock=true;
    const pg=mkProgress(saveBtn,"Save Avatar");saveBtn.textContent="Saving…";pg.pulse();
    const key="nova:user:"+_account.username.toLowerCase();
    let raw;try{raw=await redisCmd("GET",key)}catch{pg.unlock(false);avLock=false;return setMsg("av-msg","Connection error.",false);}
    let data;try{data=JSON.parse(raw||"{}")}catch{data={};}
    data.avatar=avatarVal;
    try{await redisCmd("SET",key,JSON.stringify(data))}catch{pg.unlock(false);avLock=false;return setMsg("av-msg","Error saving.",false);}
    pg.unlock(true);avLock=false;
    _account.avatar=avatarVal;localStorage.setItem("nova_account",JSON.stringify(_account));
    updateAccountUI();
    const profilePrev=document.getElementById("acct-avatar-preview");
    if(profilePrev)profilePrev.innerHTML='<img src="'+avatarVal+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%;"/>';
    setMsg("av-msg","Avatar saved!",true);toast("Avatar updated!");
  };
  const removeBtn=document.getElementById("av-remove-btn");
  if(removeBtn)removeBtn.onclick=async function(){
    const key="nova:user:"+_account.username.toLowerCase();
    let raw;try{raw=await redisCmd("GET",key)}catch{return toast("Connection error");}
    let data;try{data=JSON.parse(raw||"{}")}catch{data={};}
    data.avatar=null;
    try{await redisCmd("SET",key,JSON.stringify(data))}catch{return toast("Error");}
    _account.avatar=null;localStorage.setItem("nova_account",JSON.stringify(_account));
    updateAccountUI();_uploadedDataUrl=null;
    if(fileInput)fileInput.value="";if(urlInput)urlInput.value="";
    setAvPreview(null);
    const profilePrev=document.getElementById("acct-avatar-preview");
    if(profilePrev)profilePrev.textContent=_account.username.charAt(0).toUpperCase();
    setMsg("av-msg","","");toast("Avatar removed");
  };
})();
