// Pre-fetch games and apps in the background after Nova finishes loading
// so the search dropdown and tab switches are instant
const _deferLoad=()=>{if(!_gamesLoaded){fetch("/website/data/games.json").then(r=>r.json()).then(data=>{if(!_gamesLoaded){_allGames=data;}}).catch(()=>{})}if(!_appsLoaded){fetch("/website/data/apps.json").then(r=>r.json()).then(data=>{if(!_appsLoaded){_allApps=data;}}).catch(()=>{})}};
